-- MariaDB 11.8.8 legacy schema, captured without production rows or credentials.
CREATE TABLE plaetze(id INT PRIMARY KEY AUTO_INCREMENT,platznr VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
CREATE TABLE camper(id INT PRIMARY KEY AUTO_INCREMENT,platz_id INT NOT NULL,active TINYINT(1) NOT NULL,created DATETIME NOT NULL,updated DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,deactivated DATETIME NOT NULL DEFAULT '0000-00-00 00:00:00',Vertragskosten DECIMAL(18,2) NOT NULL DEFAULT 0,FOREIGN KEY(platz_id) REFERENCES plaetze(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
CREATE TABLE personen(id INT PRIMARY KEY AUTO_INCREMENT,anrede VARCHAR(255) NOT NULL,vorname VARCHAR(255) NOT NULL,nachname VARCHAR(255) NOT NULL,strasse VARCHAR(255) NOT NULL,plz DECIMAL(5,0) UNSIGNED ZEROFILL NOT NULL,ort VARCHAR(255) NOT NULL,created DATETIME NOT NULL,updated DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,email VARCHAR(255) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
CREATE TABLE camper_personen(id INT PRIMARY KEY AUTO_INCREMENT,camper_id INT NOT NULL,personen_id INT NOT NULL,rechnungsadresse TINYINT(1) NOT NULL,FOREIGN KEY(camper_id) REFERENCES camper(id),FOREIGN KEY(personen_id) REFERENCES personen(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
CREATE TABLE rechnungen(id INT PRIMARY KEY AUTO_INCREMENT,platz_id INT NOT NULL,alt FLOAT NOT NULL,neu FLOAT NOT NULL,verbrauch FLOAT NOT NULL,faktor FLOAT NOT NULL,betrag FLOAT NOT NULL,jahr YEAR NOT NULL,type ENUM('Strom','Wasser') NOT NULL,created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,printed TINYINT(1) NOT NULL DEFAULT 0,FOREIGN KEY(platz_id) REFERENCES plaetze(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
